package com.aliothmoon.maafw.once;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UniquePendingBusinessTest {
 static final int W=1440,H=2560;
 static byte[] beforePixels(){return SelectedPendingBusinessTest.afterPixels();}
 static List<FrameStructureEvidence.Line> beforeRows(){var r=SelectedPendingBusinessTest.afterRows();IndependentCurrentCardTest.replace(r,450,"20/25",.999988);return r;}
 static byte[] afterPixels(){byte[] p=beforePixels();IndependentCurrentCardTest.fill(p,114,1109,1326,1437,247);IndependentCurrentCardTest.fill(p,114,1109,1326,1285,255);IndependentCurrentCardTest.tick(p,1206,1165);return p;}
 static List<FrameStructureEvidence.Line> afterRows(){var r=beforeRows();r.removeIf(q->q.y()>=1109&&q.y()<1437);r.add(IndependentCurrentCardTest.r("Unmodeled card one",.99,153,1157,825,1229));r.add(IndependentCurrentCardTest.r("5",.99,1146,1160,1201,1226));IndependentCurrentCardTest.replace(r,450,"25/25",.999988);return r;}
 static LiveRewardCardObservation.Frame frame(byte[] p,List<FrameStructureEvidence.Line> rows,boolean after){return LiveRewardCardObservation.observe("unique-synthetic",1,p,W,H,rows,()->false,LiveRewardCardObservation.TargetSpec.moreUniquePending().forObservation(after));}
 @Test public void rawUniquePendingAndIndependentCompleteSetAreDifferentProofs(){var before=frame(beforePixels(),beforeRows(),false);assertEquals(before.uniqueEvidenceSummary(),LiveRewardCardObservation.Status.OBSERVED,before.status());assertTrue(before.uniqueEvidenceSummary(),before.uniqueBefore());assertEquals(5,before.cards().size());assertEquals(new com.aliothmoon.maafw.rewards.RewardRegionLocator.Box(114,1109,1326,1437),before.uniqueTarget().cardBox());var after=frame(afterPixels(),afterRows(),true);assertTrue(after.uniqueEvidenceSummary(),after.uniqueAllComplete());assertNull(after.uniqueTarget());assertFalse(after.selectedProofReady());}
 @Test public void headerFullSkipsButIsNotIndividualCompletionProof(){var r=beforeRows();IndependentCurrentCardTest.replace(r,450,"25/25",.99);var f=frame(beforePixels(),r,false);assertEquals(LiveRewardCardObservation.Status.SECTION_COMPLETE_SKIP,f.status());assertTrue(f.uniqueProofReady());assertFalse(f.uniqueAllComplete());assertNull(f.uniqueTarget());assertFalse(frame(beforePixels(),r,true).uniqueAllComplete());}

 static void title(List<FrameStructureEvidence.Line> r,String text,double score){IndependentCurrentCardTest.replace(r,1162,text,score);}
 static void held(byte[] p,List<FrameStructureEvidence.Line> r){var f=frame(p,r,false);assertFalse(f.uniqueEvidenceSummary(),f.uniqueBefore());}
 @Test public void consumedFullSplitFragmentsAndBodiesCannotBeSelected(){for(String text:List.of("Do you know the answer?","Do you know the","answer?","Quote of the day - extra","Complete this puzzle now","每日签到奖励","Ｑｕｏｔｅ","Quote of the day","Quote","Check-in","Complete this puzzle","Puzzle","签到","Challenge yourself with these trivia questions","Test your knowledge on these topics")){var r=beforeRows();title(r,text,.99);held(beforePixels(),r);r=beforeRows();r.add(IndependentCurrentCardTest.r(text,.1,150,1370,280,1400));held(beforePixels(),r);}}
 @Test public void explicitExtraStepsRiskIncludesHyphensRegistrationAndPrices(){for(String text:List.of("ＳＩＧＮ　ＩＮ","ＬＯＧＩＮ","Verify your account","Link your account","5 usd","Sign-in required","Sign‑in required","Register an account","Costs $5.99","Costs 5 USD","subscribe now","share this with friends","install app","购买","授权")){var r=beforeRows();title(r,text,.99);held(beforePixels(),r);}}
 @Test public void ordinaryQuizOrReadingOnlyMayBeOpenedWithoutDoingExtraSteps(){for(String text:List.of("Try these quiz questions","Read the latest news")){var r=beforeRows();title(r,text,.99);assertTrue(frame(beforePixels(),r,false).uniqueBefore());}}
 @Test public void punctuationMissingOrLowAuxiliaryTitleDoesNotBecomeIdentity(){for(String text:List.of("?","!!!","x")){var r=beforeRows();title(r,text,.99);r.removeIf(q->q.y()==1245);held(beforePixels(),r);}var r=beforeRows();title(r,"Read latest news",.1);held(beforePixels(),r);}
 @Test public void multiplePendingUnknownTickOrMalformedStateStops(){var p=beforePixels();IndependentCurrentCardTest.fill(p,114,1477,1326,1653,247);IndependentCurrentCardTest.fill(p,114,1477,1326,1805,255);held(p,beforeRows());for(int v=0;v<3;v++){var r=beforeRows();if(v==0)IndependentCurrentCardTest.replace(r,1234,"+10",.99);if(v==1)IndependentCurrentCardTest.replace(r,1234,"+5",.1);if(v==2)r.add(IndependentCurrentCardTest.r("+5",.99,1080,1380,1200,1410));held(beforePixels(),r);}}
 @Test public void allRowsCrossingOverlappingOrUnownedInBandAreVetoes(){for(int v=0;v<4;v++){var r=beforeRows();if(v==0)r.add(IndependentCurrentCardTest.r("Unknown crossing",.1,400,520,700,590));if(v==1)r.add(IndependentCurrentCardTest.r("Unknown gap",.1,400,1000,700,1040));if(v==2)r.add(IndependentCurrentCardTest.r("overlap",.99,390,1170,700,1200));if(v==3)r.add(IndependentCurrentCardTest.r("cross card",.99,400,1420,700,1450));held(beforePixels(),r);}}
 @Test public void consumedKnownSetMissingLowOrRegressedPendingCannotAuthorizeAnother(){for(int v=0;v<3;v++){var r=beforeRows();byte[] p=beforePixels();if(v==0)IndependentCurrentCardTest.replace(r,709,"Do you know the answer?",.1);if(v==1)r.removeIf(q->q.y()==1744);if(v==2)IndependentCurrentCardTest.fill(p,1206,717,1270,781,255);held(p,r);}}
 @Test public void ratioAmbiguityCannotSkipAndHeaderAloneNeverProvesAfter(){for(int v=0;v<3;v++){var r=beforeRows();IndependentCurrentCardTest.replace(r,450,"25/25",.99);if(v==0)r.add(IndependentCurrentCardTest.r("25/??",.1,1045,590,1257,630));if(v==1)r.add(IndependentCurrentCardTest.r("?",.1,55,440,381,536));if(v==2)IndependentCurrentCardTest.replace(r,450,"25/0",.99);assertEquals(LiveRewardCardObservation.Status.HOLD,frame(beforePixels(),r,false).status());}assertFalse(frame(beforePixels(),beforeRows(),true).uniqueAllComplete());}
 @Test public void readonlyAndLegacyFramesCannotMintUniqueBusinessProofOrLeakWords(){var o=ReadOnlyTwoStageRun.Capture.moreCurrentCards(new Object(),"readonly",W,H,0,1000,()->false).prepare(beforePixels(),W,H,beforeRows(),()->false);assertFalse(o.frame.uniqueProofReady());var f=frame(beforePixels(),beforeRows(),false);assertFalse(f.uniqueEvidenceSummary().contains("Unmodeled"));assertFalse(f.uniqueEvidenceSummary().contains("knowledge"));assertTrue(f.uniqueEvidenceSummary().length()<1000);assertFalse(SelectedPendingBusinessTest.frame(beforePixels(),beforeRows()).uniqueProofReady());}

 @Test public void completedCardsNeedOwnTickNotRepeatedTaskNames(){var rows=beforeRows();IndependentCurrentCardTest.replace(rows,709,"Anonymous first",.99);IndependentCurrentCardTest.replace(rows,1741,"Anonymous second",.99);assertTrue(frame(beforePixels(),rows,false).uniqueEvidenceSummary(),frame(beforePixels(),rows,false).uniqueBefore());rows.removeIf(q->q.y()==709||q.y()==1741);assertTrue(frame(beforePixels(),rows,false).uniqueEvidenceSummary(),frame(beforePixels(),rows,false).uniqueBefore());}

 @Test public void highOrdinaryExternalTextIsUnmodeledNotPageCoverage(){var r=beforeRows();r.add(IndependentCurrentCardTest.r("Other activity",.99,300,2200,900,2250));var f=frame(beforePixels(),r,false);assertTrue(f.uniqueBefore());assertTrue(f.uniqueEvidenceSummary().contains("unmodeledText=1"));assertTrue(f.uniqueEvidenceSummary().contains("RECOGNIZED_VISIBLE_CARDS_ONLY"));r=beforeRows();r.add(IndependentCurrentCardTest.r("Other activity",.1,300,2200,900,2250));held(beforePixels(),r);}

 @Test public void unknownLowConfidenceUInGenericCardHasNoDecorativeExemption(){var r=beforeRows();r.add(IndependentCurrentCardTest.r("?",.1,150,1370,280,1400));held(beforePixels(),r);}

 @Test public void externalCandidateSignalsRiskFragmentsOrSplitRiskRemainHeld(){for(String t:List.of("Other activity 2","+5","√","20/25","Quote","Sign-in required")){var r=beforeRows();r.add(IndependentCurrentCardTest.r(t,.99,300,2200,900,2250));held(beforePixels(),r);}var r=beforeRows();r.add(IndependentCurrentCardTest.r("Sign",.99,300,2200,900,2250));r.add(IndependentCurrentCardTest.r("in",.99,300,2260,900,2310));held(beforePixels(),r);}
}
